def check_conditions(n, table):
    # Condition 2: rows and cols
    for i in range(n):
        row = [table[i][j] for j in range(n)]
        if row.count('I') != row.count('M') or row.count('I') != row.count('O'):
            return False
    for j in range(n):
        col = [table[i][j] for i in range(n)]
        if col.count('I') != col.count('M') or col.count('I') != col.count('O'):
            return False

    # Condition 3: Diagonals
    # i-j=k
    for k in range(-(n-1), n):
        diag = []
        for i in range(n):
            j = i - k
            if 0 <= j < n:
                diag.append(table[i][j])
        if len(diag) % 3 == 0 and len(diag) > 0:
            if diag.count('I') != diag.count('M') or diag.count('I') != diag.count('O'):
                return False

    # i+j=k
    for k in range(0, 2*n-1):
        diag = []
        for i in range(n):
            j = k - i
            if 0 <= j < n:
                diag.append(table[i][j])
        if len(diag) % 3 == 0 and len(diag) > 0:
            if diag.count('I') != diag.count('M') or diag.count('I') != diag.count('O'):
                return False
    return True

def solve_small_n(n):
    # This is too slow for n >= 4.
    # For n=3, it might work.
    chars = ['I', 'M', 'O']
    for table_flat in itertools.product(chars, repeat=n*n):
        table = [table_flat[i*n:(i+1)*n] for i in range(n)]
        if check_conditions(n, table):
            return table
    return None

