def solve(n):
    table = np.full((n, n), -1)

    def is_valid(r, c, val):
        table[r, c] = val
        # Row check
        if c == n - 1:
            row = table[r]
            if np.sum(row == 0) != n//3 or np.sum(row == 1) != n//3 or np.sum(row == 2) != n//3:
                table[r, c] = -1
                return False
        # Col check
        if r == n - 1:
            col = table[:, c]
            if np.sum(col == 0) != n//3 or np.sum(col == 1) != n//3 or np.sum(col == 2) != n//3:
                table[r, c] = -1
                return False
        # Diagonal check: only when the diagonal is complete
        # This is harder. Let's check all diagonals that are completed by (r, c).
        # i-j = r-c
        k_minus = r - c
        diag_minus = []
        for i in range(n):
            j = i - k_minus
            if 0 <= j < n:
                if table[i, j] == -1:
                    # Not yet complete
                    break
                diag_minus.append(table[i, j])
        else: # Completed
            if len(diag_minus) % 3 == 0 and len(diag_minus) > 0:
                if diag_minus.count(0) != len(diag_minus)//3 or diag_minus.count(1) != len(diag_minus)//3 or diag_minus.count(2) != len(diag_minus)//3:
                    table[r, c] = -1
                    return False

        # i+j = r+c
        k_plus = r + c
        diag_plus = []
        for i in range(n):
            j = k_plus - i
            if 0 <= j < n:
                if table[i, j] == -1:
                    break
                diag_plus.append(table[i, j])
        else: # Completed
            if len(diag_plus) % 3 == 0 and len(diag_plus) > 0:
                if diag_plus.count(0) != len(diag_plus)//3 or diag_plus.count(1) != len(diag_plus)//3 or diag_plus.count(2) != len(diag_plus)//3:
                    table[r, c] = -1
                    return False

        return True

    def backtrack(r, c):
        if r == n:
            return True
        nc = c + 1
        nr = r

